<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import {writeCard,type CharacterCard} from './card-format'
import {listCardVersions,restoreCardVersion} from './card-operations'
const props=defineProps<{cardId:string}>(),emit=defineEmits<{close:[];restored:[Document<CharacterCard>]}>(),store=useLocal(),versions=ref<Document<CharacterCard>[]>([]),head=ref<Document<CharacterCard>|null>(null),selected=ref<Document<CharacterCard>|null>(null),hasMore=ref(false),busy=ref(false),error=ref(''),controller=new AbortController()
let disposed=false
async function load(more=false){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const result=await listCardVersions(vault,props.cardId,more?versions.value.at(-1)?.revision:undefined);if(disposed||store.vault!==vault||!vault.unlocked)return;head.value=result.head;versions.value=more?[...versions.value,...result.rows]:result.rows;hasMore.value=result.hasMore;if(!selected.value)selected.value=result.rows[0]||null}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function restore(){const vault=store.vault,row=head.value,target=selected.value;if(!vault||!row||!target||busy.value||target.revision===row.revision)return;busy.value=true;error.value='';try{const result=await restoreCardVersion(vault,row,target.revision,crypto.randomUUID(),controller.signal);if(disposed||controller.signal.aborted||store.vault!==vault||!vault.unlocked)return;emit('restored',result);emit('close')}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{busy.value=false}}
function json(){try{return selected.value?writeCard(selected.value.value):''}catch(e){return (e as Error).message}}
function close(){disposed=true;controller.abort();emit('close')}
onMounted(()=>void load())
onUnmounted(()=>{disposed=true;controller.abort()})
</script>
<template><Sheet title="角色修订" @close="close"><div class="card-history-panel"><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="card-revisions"><button v-for="row in versions" :key="row.revision" :aria-pressed="selected?.revision===row.revision" :disabled="busy" @click="selected=row"><strong>v{{row.revision}}</strong><span>{{new Date(row.updatedAt).toLocaleString()}}</span><small v-if="row.revision===head?.revision">当前</small></button><button v-if="hasMore" :disabled="busy" @click="load(true)">更早的修订</button></div><article v-if="selected" class="card-revision-preview"><h2>{{selected.value.name}}</h2><p>{{selected.value.description}}</p><dl><template v-if="selected.value.personality"><dt>性格</dt><dd>{{selected.value.personality}}</dd></template><template v-if="selected.value.firstMessage"><dt>开场</dt><dd>{{selected.value.firstMessage}}</dd></template></dl><details><summary>完整角色卡</summary><pre>{{json()}}</pre></details><button v-if="selected.revision!==head?.revision" class="final-primary" :disabled="busy" @click="restore">{{busy?'正在恢复…':'恢复这个版本'}}</button></article></div></Sheet></template>
<style scoped>.card-history-panel{display:grid;gap:24px}.card-revisions{display:grid;gap:8px}.card-revisions button{display:flex;align-items:center;gap:14px;text-align:left;padding:12px 14px;border:1px solid var(--edge);border-radius:9px}.card-revisions button[aria-pressed=true]{border-color:var(--accent);background:var(--wash);color:var(--accent)}.card-revisions span{font-size:12px;flex:1;color:var(--quiet)}.card-revisions small{font-size:11px}.card-revision-preview h2{font:26px var(--font-serif,serif)}.card-revision-preview p,.card-revision-preview dd{line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto}.card-revision-preview dd{margin:8px 0 20px;color:var(--quiet)}.card-revision-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;font-size:12px}.card-revision-preview button{margin-top:20px}</style>
